int dist[N], q[N*2], arc[N], gap[N], inq[N], pre[N];

int SAP(int s, int t) {
    memset(arc, -1, sizeof(arc));
    memset(pre, -1, sizeof(pre));
    int qf=0, qr=0;
    q[qr++]=t; inq[t]=1; gap[0]++;
    dist[t]=0;
