        int u=q[qf++];
        for(auto i:adj[u]){
            int v=edges[i].v;
            if(!inq[v]){
                q[qr++]=v;
                inq[v]=1;
                dist[v]=dist[u]+1;
                gap[dist[v]]++;
                arc[v]=i;
            }
        }
    }
    int low=INF, u=s, ans=0;
    pre[s]=s;
    while(dist[s]<t){
        bool flag=false;
        for(int &i=arc[u];i!=-1;i=adj[u][i]){
            if(edges[i].w && dist[edges[i].v]+1==dist[u]){
                flag=true;
                low=min(low,edges[i].w);
                pre[edges[i].v]=u;
                u=edges[i].v;
                if(u==t){
                    while(u!=s){
                        int i=pre[u];
                        edges[i].w-=low;
                        edges[i^1].w+=low;
                        u=pre[u];
                    }
                    ans+=low;
                    low=INF;
                }
                break;
            }
        }
        if(flag) continue;
        int mindis=t+1;
        for(auto i:adj[u]){
            int v=edges[i].v;
            if(edges[i].w && dist[v]<mindis){
                mindis=dist[v];
                arc[u]=i;
            }
        }
        gap[dist[u]]--;
        if(gap[dist[u]]==0) return ans;
        dist[u]=mindis+1;
        gap[dist[u]]++;
        u=pre[u];
    }
    return ans;
}

